125	    // Code session on v3.10.37 under exactly this pattern (MCP startup
126	    // racing with a sibling invocation).
127	    //
128	    // Fix: hold the lock across the entire spawn lifecycle (dedup check →
129	    // killStaleDaemons → fork → PID file write), so the lock-loser ALWAYS
130	    // sees either a live lock or a populated PID file, never the empty
131	    // window in between.
132	    let lockFd: number | null = null;
133	    let lockFile = '';
134	    if (!isDaemonProcess) {
135	      const stateDir = join(resolve(projectRoot), '.claude-flow');
136	      lockFile = join(stateDir, 'daemon.lock');
137	      try { fs.mkdirSync(stateDir, { recursive: true }); } catch { /* exists */ }
138	      try {
139	        lockFd = fs.openSync(lockFile, fs.constants.O_CREAT | fs.constants.O_EXCL | fs.constants.O_WRONLY);
140	        fs.writeSync(lockFd, String(process.pid));
141	      } catch (e) {
142	        if ((e as NodeJS.ErrnoException).code === 'EEXIST') {
